import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第六十四卦 未濟 火水未濟 離上坎下","description":"周易 - 第六十四卦 未濟 火水未濟 離上坎下","frontmatter":{"title":"第六十四卦 未濟 火水未濟 離上坎下","description":"周易 - 第六十四卦 未濟 火水未濟 離上坎下"},"headers":[],"relativePath":"classics/zhouyi/065.md","filePath":"classics/zhouyi/065.md"}'),l={name:"classics/zhouyi/065.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，小狐汔濟，濡其尾，無攸利。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>未濟，亨；柔得中也。小狐汔濟，未出中也。濡其尾，無攸利；不續終也。雖不當位，剛柔應也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>火在水上，未濟；君子以慎辨物居方。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>濡其尾，吝。象曰：濡其尾，亦不 知極也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>曳其輪，貞吉。象曰：九二貞吉，中以行正也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>未濟，徵兇，利涉大川。象曰：未濟徵兇，位不當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>貞吉，悔亡，震用伐鬼方，三年有賞於大國。象曰：貞吉悔亡，志行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>貞吉，無悔，君子之光，有孚，吉。象曰：君子之光，其暉吉也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>有孚於飲酒，無咎，濡其首，有孚失是。象曰：飲酒濡首，亦不知節也</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
